# Build the F-002 guest actors into signed VOS3 packages. Runs INSIDE the
# Linux container (see spikes/README.md): VOS saga 7bae926 mounted at /vos,
# `vosx` built from it on PATH, this directory mounted at /spikes-guest, and
# packages written to /out.
#
# The actor scaffolding (target spec, linker script, cargo alias, toolchain)
# is generated by `vosx actor new`, so it is always the pinned VOS's own.
#
#   build.sh [kernel-probe|state-blob] [extra cargo features...]
set -euo pipefail
actor=${1:?actor}
shift || true
features="${*:-}"
work=/work/$actor${features:+-${features// /-}}
rm -rf "$work" /tmp/scaffold
mkdir -p /work /out
vosx actor new /tmp/scaffold >/dev/null
cp -r "/spikes-guest/$actor" "$work"
cp -r /tmp/scaffold/.cargo /tmp/scaffold/pvm.ld /tmp/scaffold/riscv64em-vos.json \
      /tmp/scaffold/rust-toolchain.toml "$work"/
if [ -n "$features" ]; then
  # `vosx actor build` has no feature switch: make the features default.
  sed -i "s/^default = \[\"bin\"\]/default = [\"bin\", $(printf '"%s", ' $features | sed 's/, $//')]/" "$work/Cargo.toml"
fi
name=$actor${features:+-${features// /-}}
vosx actor build "$work" --name "$name" --out-dir /out
ls -l /out
